using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Web.Script.Serialization;
using System.Windows.Forms;

// Uses report pages generated by the frozen fixture. No analyzer is launched.
public static class ConfigUrFormContract {
    static int checks;
    const BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
    static T Field<T>(ConfigUrForm form,string name) {
        return (T)typeof(ConfigUrForm).GetField(name,Private).GetValue(form);
    }
    static void Check(bool value,string name) {
        checks++;
        if(!value)throw new Exception(name);
    }
    [STAThread] public static void Main(string[] args) {
        try {Run(args); Console.WriteLine("Config UR UI assertions="+checks);}
        catch(Exception error) {Console.WriteLine(error);Environment.ExitCode=1;}
    }
    static void Run(string[] args) {
        string folder=args[0], relative=args[1], indexPath=ConfigUrForm.ResolveIndex(folder,relative);
        var binding=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(indexPath));
        string id=(string)binding["analysis_id"];
        var actions=new List<string>();
        var ready=new Dictionary<string,object>{{"state","ready"},{"index",relative}};
        using(var form=new ConfigUrForm(folder,id,binding,()=>actions.Add("run"),()=>actions.Add("cancel"),
            (row,target)=>actions.Add(row+" "+target))) {
            var rows=Field<DataGridView>(form,"results");
            var targets=Field<Button[]>(form,"openTargets");
            string pagePath=Path.Combine(Path.GetDirectoryName(indexPath),"writes-0.json");
            using(var held=new FileStream(pagePath,FileMode.Open,FileAccess.Read,FileShare.None)){
                form.ApplyStatus(ready,false,true,false);
                Check(rows.Rows.Count==0,"no rows when the first page cannot be read");
            }
            form.ApplyStatus(ready,false,true,false);
            Check(rows.Rows.Count==6,"retry loads the same bound page");
            rows.CurrentCell=rows.Rows[4].Cells[0];
            Check(targets[0].Enabled&&targets[1].Enabled&&targets[2].Enabled&&targets[3].Enabled,
                "all four proven locations available");
            var navigate=typeof(ConfigUrForm).GetMethod("NavigateSelected",Private);
            navigate.Invoke(form,new object[]{1});
            navigate.Invoke(form,new object[]{3});
            Check(actions.Count==2&&actions[0]=="p2160355 completion"&&actions[1]=="p2160355 read_completion",
                "native actions send row IDs and target kinds");
            Check(Field<RichTextBox>(form,"evidence").Text.Contains("2309449"),"readback evidence visible");
            rows.CurrentCell=rows.Rows[0].Cells[0];
            Check(targets[0].Enabled&&!targets[1].Enabled&&!targets[2].Enabled,"unknown directions unavailable");
            var filter=Field<ComboBox>(form,"filter");
            filter.SelectedIndex=2;
            Check(rows.Rows.Count==9,"nine memory UR rows visible");
            filter.SelectedIndex=3;
            Check(rows.Rows.Count==3&&!targets[0].Enabled,"UR aggregates do not impersonate packets");
            form.ApplyStatus(new Dictionary<string,object>{{"state","running"}},true,true,true);
            Check(Field<Button>(form,"cancel").Enabled&&!Field<Button>(form,"export").Enabled,
                "running supplement can be cancelled");
            form.ApplyStatus(new Dictionary<string,object>{{"state","error"}},false,true,false);
            Check(rows.Rows.Count==3&&!Field<Button>(form,"export").Enabled&&Field<Button>(form,"run").Enabled,
                "error leaves prior evidence visible and allows retry");
            form.ApplyStatus(new Dictionary<string,object>{{"state","ready"},{"index","../index.json"}},false,true,false);
            Check(Field<Label>(form,"status").Text.Contains("讀取失敗")&&!Field<Button>(form,"export").Enabled,
                "outside paths are rejected");
        }
        var mismatched=new Dictionary<string,object>(binding);
        mismatched["display_trace_sha256"]=new string('f',64);
        using(var form=new ConfigUrForm(folder,id,mismatched,()=>{},()=>{},(row,target)=>{})) {
            form.ApplyStatus(ready,false,true,false);
            Check(Field<DataGridView>(form,"results").Rows.Count==0&&!Field<Button>(form,"export").Enabled,
                "display hash mismatch rejects all report actions");
        }
    }
}
